export const __DEVICE_FILES__ = {"/lib/ext/smart_gbw/grind_config.py":"\"\"\"Tuning constants ported from smart-grind-by-weight src/config/grind_control.h.\n\nChange via edit + reload; values that should persist across reboots go through\nprofile_controller/statistics_manager instead.\n\"\"\"\n\n# ---- Accuracy and timeouts ---------------------------------------------------\nACCURACY_TOLERANCE_G = 0.03          # Final accuracy tolerance\nTIMEOUT_SEC = 60                     # Max time for a grind session\nMAX_PULSE_ATTEMPTS = 10              # Max pulse corrections before stopping\n\n# ---- Flow detection ----------------------------------------------------------\nFLOW_DETECTION_THRESHOLD_GPS = 0.5   # Min flow rate to mark \"coffee reached cup\"\n\n# ---- Undershoot strategy -----------------------------------------------------\nUNDERSHOOT_TARGET_G = 1.0            # Default conservative undershoot\nLATENCY_TO_COAST_RATIO = 1.0         # Coast time multiplier vs measured latency\n\n# ---- Prime / purge -----------------------------------------------------------\nPURGE_MODE_DEFAULT = 1               # 0 = PRIME, 1 = PURGE\nPURGE_AMOUNT_DEFAULT_G = 1.0\nPURGE_AMOUNT_MIN_G = 0.1\nPURGE_AMOUNT_MAX_G = 2.5\nFRESHNESS_DEFAULT_HOURS = 8.0\nPRIME_TARGET_WEIGHT_G = 1.0\nPRIME_MAX_DURATION_MS = 5000\n\n# ---- Settling ----------------------------------------------------------------\nSCALE_SETTLING_TOLERANCE_G = 0.010\nSCALE_PRECISION_SETTLING_TIME_MS = 500\nSCALE_SETTLING_TIMEOUT_MS = 10000\nMOTOR_SETTLING_TIME_MS = 200\n\n# ---- Flow rate bounds --------------------------------------------------------\nFLOW_RATE_MIN_SANE_GPS = 1.0\nFLOW_RATE_MAX_SANE_GPS = 3.0\nPULSE_FLOW_RATE_FALLBACK_GPS = 1.5\n\n# ---- Motor ------------------------------------------------------------------\nMOTOR_RESPONSE_LATENCY_DEFAULT_MS = 50.0\nMOTOR_MAX_PULSE_DURATION_MS = 250.0\nTIME_PULSE_DURATION_MS = 100\n\n# ---- Tare / calibration timing ----------------------------------------------\nTARE_SAMPLE_WINDOW_MS = 500\nTARE_TIMEOUT_MS = 3000\nCALIBRATION_SAMPLE_WINDOW_MS = 800\nCALIBRATION_TIMEOUT_MS = 2000\n\n# ---- Load cell sample rate --------------------------------------------------\n# HX711 in 80 SPS mode gives ~12.5 ms per sample. Set conservatively.\nLOADCELL_SAMPLE_INTERVAL_MS = 20\n\n# ---- Mechanical instability detection ---------------------------------------\nMECHANICAL_DROP_THRESHOLD_G = 0.4\nMECHANICAL_EVENT_COOLDOWN_MS = 200\nMECHANICAL_EVENT_REQUIRED_COUNT = 3\n\n\nclass Mode:\n    WEIGHT = 0\n    TIME = 1\n\n\nclass Profile:\n    SINGLE = 0\n    DOUBLE = 1\n    CUSTOM = 2\n\n\nclass Phase:\n    IDLE = 0\n    INITIALIZING = 1\n    SETUP = 2\n    TARING = 3\n    TARE_CONFIRM = 4\n    PREDICTIVE = 5\n    PULSE_DECISION = 6\n    PULSE_EXECUTE = 7\n    PULSE_SETTLING = 8\n    FINAL_SETTLING = 9\n    TIME_GRINDING = 10\n    TIME_ADDITIONAL_PULSE = 11\n    COMPLETED = 12\n    TIMEOUT = 13\n    PRIME = 14\n    PRIME_SETTLING = 15\n    PURGE_CONFIRM = 16\n\n\nPHASE_NAMES = {\n    getattr(Phase, k): k for k in dir(Phase) if not k.startswith(\"_\")\n}\n\n\nclass Result:\n    UNKNOWN = 0\n    SUCCESS = 1\n    OVERSHOOT = 2\n    MAX_PULSES = 3\n    TIMEOUT = 4\n    ERROR = 5\n\n\nRESULT_NAMES = {\n    getattr(Result, k): k for k in dir(Result) if not k.startswith(\"_\")\n}\n","/lib/ext/smart_gbw/grind_controller.py":"\"\"\"Predictive grind controller.\n\nPython port of src/controllers/grind_controller.cpp. Algorithm:\n\n    TARING ─> PREDICTIVE (learn latency+flow, compute motor_stop_target)\n           ─> FINAL_SETTLING ─> PULSE_DECISION\n                                   │\n                 within tolerance ─┴─> COMPLETED\n                 overshoot         ──> COMPLETED (overshoot)\n                 undershoot        ──> PULSE_EXECUTE -> PULSE_SETTLING ─┐\n                                                                        │\n                                        (up to MAX_PULSE_ATTEMPTS) ─────┘\n\nThe controller is driven by `update()` called from a timer/thread at\n~20 ms cadence. All timing uses time.ticks_ms.\n\"\"\"\n\nimport time\n\nfrom lib.ext.smart_gbw import grind_config as C\n\n\nclass _Event:\n    def __init__(self, kind, **payload):\n        self.t = time.ticks_ms()\n        self.kind = kind\n        self.payload = payload\n\n    def as_dict(self):\n        d = {\"t\": self.t, \"kind\": self.kind}\n        d.update(self.payload)\n        return d\n\n\nclass GrindController:\n    def __init__(self, sensor, grinder, profile_controller, statistics, event_sink=None):\n        self.sensor = sensor\n        self.grinder = grinder\n        self.profiles = profile_controller\n        self.stats = statistics\n        self.event_sink = event_sink  # callable(dict) for UI + log\n\n        self.phase = C.Phase.IDLE\n        self.mode = C.Mode.WEIGHT\n        self.target_weight = 0.0\n        self.target_time_ms = 0\n        self.tolerance = C.ACCURACY_TOLERANCE_G\n\n        self._start_ms = 0\n        self._phase_start_ms = 0\n\n        # predictive state\n        self._grind_latency_ms = 0.0\n        self._flow_rate_gps = 0.0\n        self._motor_stop_target = 0.0\n        self._flow_start_confirmed = False\n\n        # pulse state\n        self._pulse_attempts = 0\n        self._pulse_history = []  # list of (start_w, end_w, duration_ms)\n        self._pulse_flow_rate = C.PULSE_FLOW_RATE_FALLBACK_GPS\n        self._current_pulse_ms = 0.0\n        self._motor_response_latency_ms = C.MOTOR_RESPONSE_LATENCY_DEFAULT_MS\n\n        # session result\n        self.last_result = C.Result.UNKNOWN\n        self._final_weight = 0.0\n        self._session = None  # dict being accumulated for statistics\n\n    # ----- public API ---------------------------------------------------------\n    def start_weight(self, target_g, profile_id=None):\n        self._begin_session(C.Mode.WEIGHT, target_g, 0, profile_id)\n\n    def start_time(self, target_ms, profile_id=None):\n        self._begin_session(C.Mode.TIME, 0.0, target_ms, profile_id)\n\n    def stop(self):\n        self.grinder.stop()\n        self._switch(C.Phase.COMPLETED)\n        self._finalize(C.Result.UNKNOWN)\n\n    def is_active(self):\n        return self.phase not in (C.Phase.IDLE, C.Phase.COMPLETED, C.Phase.TIMEOUT)\n\n    def get_phase(self):\n        return self.phase\n\n    # ----- update loop --------------------------------------------------------\n    def update(self):\n        if self.phase == C.Phase.IDLE:\n            return\n\n        now = time.ticks_ms()\n        elapsed = time.ticks_diff(now, self._start_ms)\n        if elapsed > C.TIMEOUT_SEC * 1000 and self.is_active():\n            self.grinder.stop()\n            self._switch(C.Phase.TIMEOUT)\n            self._finalize(C.Result.TIMEOUT)\n            return\n\n        if self.mode == C.Mode.TIME:\n            self._update_time_mode(now)\n        else:\n            self._update_weight_mode(now)\n\n    # ----- mode dispatchers ---------------------------------------------------\n    def _update_time_mode(self, now):\n        if self.phase == C.Phase.TIME_GRINDING:\n            if time.ticks_diff(now, self._phase_start_ms) >= self.target_time_ms:\n                self.grinder.stop()\n                self._switch(C.Phase.FINAL_SETTLING)\n        elif self.phase == C.Phase.FINAL_SETTLING:\n            if self.sensor.is_settled() or time.ticks_diff(now, self._phase_start_ms) > C.SCALE_SETTLING_TIMEOUT_MS:\n                self._final_weight = self.sensor.current()\n                self._switch(C.Phase.COMPLETED)\n                self._finalize(C.Result.SUCCESS)\n\n    def _update_weight_mode(self, now):\n        if self.phase == C.Phase.TARING:\n            if self.sensor.is_settled() or time.ticks_diff(now, self._phase_start_ms) > C.TARE_TIMEOUT_MS:\n                self.sensor.tare()\n                self.grinder.start()\n                self._flow_start_confirmed = False\n                self._switch(C.Phase.PREDICTIVE)\n\n        elif self.phase == C.Phase.PREDICTIVE:\n            self._predictive_tick(now)\n\n        elif self.phase == C.Phase.FINAL_SETTLING:\n            if self.sensor.is_settled() or time.ticks_diff(now, self._phase_start_ms) > C.SCALE_SETTLING_TIMEOUT_MS:\n                self._final_weight = self.sensor.current()\n                self._switch(C.Phase.PULSE_DECISION)\n\n        elif self.phase == C.Phase.PULSE_DECISION:\n            self._pulse_decision()\n\n        elif self.phase == C.Phase.PULSE_EXECUTE:\n            if time.ticks_diff(now, self._phase_start_ms) >= self._current_pulse_ms:\n                self.grinder.stop()\n                self._switch(C.Phase.PULSE_SETTLING)\n\n        elif self.phase == C.Phase.PULSE_SETTLING:\n            if self.sensor.is_settled() or time.ticks_diff(now, self._phase_start_ms) > C.SCALE_SETTLING_TIMEOUT_MS:\n                self._record_pulse_outcome()\n                self._final_weight = self.sensor.current()\n                self._switch(C.Phase.PULSE_DECISION)\n\n    # ----- predictive phase ---------------------------------------------------\n    def _predictive_tick(self, now):\n        current = self.sensor.current()\n        flow = self.sensor.flow_rate_gps()\n\n        # Learn latency the first time flow exceeds detection threshold.\n        if not self._flow_start_confirmed and flow >= C.FLOW_DETECTION_THRESHOLD_GPS:\n            self._flow_start_confirmed = True\n            self._grind_latency_ms = float(time.ticks_diff(now, self._phase_start_ms))\n            self._emit(\"flow_start\", latency_ms=self._grind_latency_ms)\n\n        # Update flow rate estimate once flow is established.\n        if self._flow_start_confirmed and C.FLOW_RATE_MIN_SANE_GPS <= flow <= C.FLOW_RATE_MAX_SANE_GPS:\n            self._flow_rate_gps = flow\n            coast_ms = self._grind_latency_ms * C.LATENCY_TO_COAST_RATIO\n            coast_weight = (coast_ms / 1000.0) * flow\n            self._motor_stop_target = self.target_weight - coast_weight\n            self._pulse_flow_rate = flow\n\n        # Stop the motor once predicted stop weight reached.\n        if self._flow_start_confirmed and current >= self._motor_stop_target:\n            self.grinder.stop()\n            self._switch(C.Phase.FINAL_SETTLING)\n\n    # ----- pulse phase --------------------------------------------------------\n    def _pulse_decision(self):\n        error = self.target_weight - self._final_weight\n        abs_error = abs(error)\n\n        if abs_error <= self.tolerance:\n            self._switch(C.Phase.COMPLETED)\n            self._finalize(C.Result.SUCCESS)\n            return\n\n        if error < 0:  # overshoot\n            self._switch(C.Phase.COMPLETED)\n            self._finalize(C.Result.OVERSHOOT)\n            return\n\n        if self._pulse_attempts >= C.MAX_PULSE_ATTEMPTS:\n            self._switch(C.Phase.COMPLETED)\n            self._finalize(C.Result.MAX_PULSES)\n            return\n\n        flow = self._pulse_flow_rate if self._pulse_flow_rate > 0 else C.PULSE_FLOW_RATE_FALLBACK_GPS\n        raw_ms = (error / flow) * 1000.0\n        pulse_ms = self._motor_response_latency_ms + raw_ms\n        pulse_ms = max(self._motor_response_latency_ms,\n                       min(self._motor_response_latency_ms + C.MOTOR_MAX_PULSE_DURATION_MS, pulse_ms))\n        self._current_pulse_ms = pulse_ms\n        self._pulse_attempts += 1\n        self._pulse_start_weight = self.sensor.current()\n        self.grinder.start()\n        self._switch(C.Phase.PULSE_EXECUTE)\n\n    def _record_pulse_outcome(self):\n        end_w = self.sensor.current()\n        self._pulse_history.append((self._pulse_start_weight, end_w, self._current_pulse_ms))\n\n    # ----- session plumbing ---------------------------------------------------\n    def _begin_session(self, mode, target_weight, target_time_ms, profile_id):\n        self.mode = mode\n        self.target_weight = target_weight\n        self.target_time_ms = target_time_ms\n        self._start_ms = time.ticks_ms()\n        self._pulse_attempts = 0\n        self._pulse_history = []\n        self._grind_latency_ms = 0.0\n        self._flow_rate_gps = 0.0\n        self._motor_stop_target = target_weight - C.UNDERSHOOT_TARGET_G\n        self._flow_start_confirmed = False\n        self._final_weight = 0.0\n        self.last_result = C.Result.UNKNOWN\n\n        self._session = {\n            \"started_at\": time.time() if hasattr(time, \"time\") else 0,\n            \"mode\": mode,\n            \"profile_id\": profile_id,\n            \"target_weight\": target_weight,\n            \"target_time_ms\": target_time_ms,\n            \"events\": [],\n            \"measurements\": [],\n        }\n        self._emit(\"session_start\", mode=mode, target_weight=target_weight, target_time_ms=target_time_ms)\n\n        if mode == C.Mode.TIME:\n            self.grinder.start()\n            self._switch(C.Phase.TIME_GRINDING)\n        else:\n            self._switch(C.Phase.TARING)\n\n    def _finalize(self, result):\n        self.last_result = result\n        if self._session is None:\n            return\n        self._session[\"result\"] = result\n        self._session[\"final_weight\"] = self._final_weight\n        self._session[\"pulse_count\"] = self._pulse_attempts\n        self._session[\"grind_latency_ms\"] = self._grind_latency_ms\n        self._session[\"flow_rate_gps\"] = self._flow_rate_gps\n        self._session[\"pulses\"] = self._pulse_history\n        self._emit(\"session_end\", result=result, final_weight=self._final_weight,\n                   pulse_count=self._pulse_attempts)\n        try:\n            self.stats.record_session(self._session)\n        except Exception as e:\n            self._emit(\"session_persist_error\", error=str(e))\n        self._session = None\n        self.phase_after_idle_ms = time.ticks_ms()\n\n    # ----- helpers ------------------------------------------------------------\n    def _switch(self, new_phase):\n        if new_phase == self.phase:\n            return\n        self._emit(\"phase\", frm=self.phase, to=new_phase)\n        self.phase = new_phase\n        self._phase_start_ms = time.ticks_ms()\n\n    def _emit(self, kind, **payload):\n        ev = _Event(kind, **payload).as_dict()\n        if self._session is not None:\n            self._session[\"events\"].append(ev)\n        if self.event_sink:\n            try:\n                self.event_sink(ev)\n            except Exception:\n                pass\n","/lib/ext/smart_gbw/grind_helpers.py":"\"\"\"What SmartGBW's tools do. Each tool in tools/ calls one function here with its checked\narguments, and returns what it returns. A ValueError's text is the tool's error.\n\n- Sessions and profiles are read from their files, so they answer whether or not SmartGBW\n  is running.\n- The live ones (state, tare, calibrate, start, stop) need it running, which binds the\n  controller and the sensor here.\n\"\"\"\n\nfrom lib.ext.smart_gbw import grind_config as C\n\nNOT_RUNNING = \"SmartGBW is not running on this board.\"\n\n_ctx = {\n    \"controller\": None,\n    \"statistics\": None,\n    \"profiles\": None,\n    \"sensor\": None,\n}\n\n\ndef bind(controller, statistics, profiles, sensor):\n    _ctx[\"controller\"] = controller\n    _ctx[\"statistics\"] = statistics\n    _ctx[\"profiles\"] = profiles\n    _ctx[\"sensor\"] = sensor\n\n\ndef _stats():\n    s = _ctx[\"statistics\"]\n    if s is None:\n        from lib.ext.smart_gbw.statistics import StatisticsManager\n        s = StatisticsManager()\n        _ctx[\"statistics\"] = s\n    return s\n\n\ndef _profiles():\n    p = _ctx[\"profiles\"]\n    if p is None:\n        from lib.ext.smart_gbw.profile_controller import ProfileController\n        p = ProfileController()\n        _ctx[\"profiles\"] = p\n    return p\n\n\ndef _running(name):\n    part = _ctx[name]\n    if part is None:\n        raise ValueError(NOT_RUNNING)\n    return part\n\n\n# ----- state --------------------------------------------------------------\ndef state():\n    c = _ctx[\"controller\"]\n    s = _ctx[\"sensor\"]\n    if c is None or s is None:\n        from lib.ext.smart_gbw import smart_gbw\n        return {\"running\": False, \"wired\": smart_gbw.wiring() is not None}\n    return {\n        \"running\": True,\n        \"weight_g\": s.current(),\n        \"flow_gps\": s.flow_rate_gps(),\n        \"phase\": c.phase,\n        \"phase_name\": C.PHASE_NAMES.get(c.phase, \"UNKNOWN\"),\n        \"mode\": c.mode,\n        \"target_weight_g\": c.target_weight,\n        \"target_time_ms\": c.target_time_ms,\n        \"last_result\": c.last_result,\n        \"last_result_name\": C.RESULT_NAMES.get(c.last_result, \"UNKNOWN\"),\n        \"pulse_count\": c._pulse_attempts,\n        \"is_calibrated\": s.is_calibrated(),\n    }\n\n\n# ----- profiles -----------------------------------------------------------\ndef profiles():\n    p = _profiles()\n    return {\"active\": p.active_id, \"profiles\": p.profiles}\n\n\ndef select_profile(profile_id):\n    p = _profiles()\n    p.set_active(profile_id)\n    return {\"active\": p.active_id}\n\n\ndef update_profile(profile_id, target_g=None, target_ms=None):\n    fields = {}\n    if target_g is not None:\n        fields[\"target_g\"] = target_g\n    if target_ms is not None:\n        fields[\"target_ms\"] = target_ms\n    if not fields:\n        raise ValueError(\"Give target_g or target_ms\")\n    _profiles().update(profile_id, **fields)\n    return profiles()\n\n\n# ----- sessions -----------------------------------------------------------\n_SUMMARY = (\n    \"started_at\", \"mode\", \"profile_id\", \"target_weight\", \"target_time_ms\",\n    \"result\", \"final_weight\", \"pulse_count\", \"grind_latency_ms\",\n    \"flow_rate_gps\",\n)\n\n\ndef summaries(limit=None, offset=0):\n    \"\"\"One row per session, without its weight samples.\"\"\"\n    out = [{k: sess.get(k) for k in _SUMMARY} for sess in _stats().iter_sessions(limit=limit, offset=offset)]\n    return {\"summaries\": out, \"offset\": offset, \"count\": _stats().count_sessions()}\n\n\ndef sessions(limit=1, offset=0):\n    \"\"\"Whole sessions, each with its weight samples.\"\"\"\n    out = [sess for sess in _stats().iter_sessions(limit=limit, offset=offset)]\n    return {\"sessions\": out, \"offset\": offset}\n\n\n# ----- the scale ----------------------------------------------------------\ndef tare():\n    _running(\"sensor\").tare()\n    return {\"tared\": True}\n\n\ndef calibrate(known_g):\n    s = _running(\"sensor\")\n    raw = s._hx.read_average(15) - s._hx.OFFSET\n    scale = raw / known_g\n    s.set_scale(scale)\n    s.save_calibration()\n    return {\"scale\": scale}\n\n\n# ----- grinding -----------------------------------------------------------\ndef start(profile_id=None):\n    c = _running(\"controller\")\n    if c.is_active():\n        raise ValueError(\"A grind is already running\")\n    p = _profiles()\n    profile = p.get(profile_id)\n    chosen = p.active_id if profile_id is None else profile_id\n    if profile[\"mode\"] == C.Mode.WEIGHT:\n        c.start_weight(profile[\"target_g\"], profile_id=chosen)\n    else:\n        c.start_time(profile[\"target_ms\"], profile_id=chosen)\n    return {\"started\": True, \"profile_id\": chosen}\n\n\ndef stop():\n    _running(\"controller\").stop()\n    return {\"stopped\": True}\n","/lib/ext/smart_gbw/grinder.py":"\"\"\"Grinder motor relay control. Port of src/hardware/grinder.cpp.\"\"\"\n\nimport time\nfrom machine import Pin\n\n\nclass Grinder:\n    def __init__(self, relay_pin, active_high=True):\n        self._pin = Pin(relay_pin, Pin.OUT)\n        self._active_high = active_high\n        self._on = False\n        self._last_toggle_ms = time.ticks_ms()\n        self.stop()\n\n    def start(self):\n        if not self._on:\n            self._pin.value(1 if self._active_high else 0)\n            self._on = True\n            self._last_toggle_ms = time.ticks_ms()\n\n    def stop(self):\n        if self._on or self._last_toggle_ms == time.ticks_ms():\n            self._pin.value(0 if self._active_high else 1)\n            self._on = False\n            self._last_toggle_ms = time.ticks_ms()\n\n    def pulse(self, duration_ms):\n        self.start()\n        time.sleep_ms(duration_ms)\n        self.stop()\n\n    def is_on(self):\n        return self._on\n","/lib/ext/smart_gbw/hx711_gpio.py":"# MIT License\n\n# Copyright (c) 2019 \n\n# Permission is hereby granted, free of charge, to any person obtaining a copy\n# of this software and associated documentation files (the \"Software\"), to deal\n# in the Software without restriction, including without limitation the rights\n# to use, copy, modify, merge, publish, distribute, sublicense, and/or sell\n# copies of the Software, and to permit persons to whom the Software is\n# furnished to do so, subject to the following conditions:\n\n# The above copyright notice and this permission notice shall be included in all\n# copies or substantial portions of the Software.\n\n# THE SOFTWARE IS PROVIDED \"AS IS\", WITHOUT WARRANTY OF ANY KIND, EXPRESS OR\n# IMPLIED, INCLUDING BUT NOT LIMITED TO THE WARRANTIES OF MERCHANTABILITY,\n# FITNESS FOR A PARTICULAR PURPOSE AND NONINFRINGEMENT. IN NO EVENT SHALL THE\n# AUTHORS OR COPYRIGHT HOLDERS BE LIABLE FOR ANY CLAIM, DAMAGES OR OTHER\n# LIABILITY, WHETHER IN AN ACTION OF CONTRACT, TORT OR OTHERWISE, ARISING FROM,\n# OUT OF OR IN CONNECTION WITH THE SOFTWARE OR THE USE OR OTHER DEALINGS IN THE\n# SOFTWARE.\n\nfrom machine import enable_irq, disable_irq, idle, Pin\nimport time\n\nclass HX711:\n    def __init__(self, clock, data, gain=128):\n        self.clock = clock\n        self.data = data\n        self.clock.value(False)\n\n        self.GAIN = 0\n        self.OFFSET = 0\n        self.SCALE = 1\n\n        self.time_constant = 0.25\n        self.filtered = 0\n\n        # determine the number of attempts to find the trigger pulse\n        start = time.ticks_us()\n        for _ in range(3):\n            temp = self.data()\n        spent = time.ticks_diff(time.ticks_us(), start)\n        self.__wait_loop = 3_000_000 // spent\n\n        self.set_gain(gain);\n\n    def __call__(self):\n        return self.read()\n\n    def set_gain(self, gain):\n        if gain is 128:\n            self.GAIN = 1\n        elif gain is 64:\n            self.GAIN = 3\n        elif gain is 32:\n            self.GAIN = 2\n\n        self.read()\n        self.filtered = self.read()\n\n    def conversion_done_cb(self, data):\n        self.conversion_done = True\n        data.irq(handler=None)\n\n    def read(self):\n        if hasattr(self.data, \"irq\"):\n            self.conversion_done = False\n            self.data.irq(trigger=Pin.IRQ_FALLING, handler=self.conversion_done_cb)\n            # wait for the device being ready\n            for _ in range(500):\n                if self.conversion_done == True:\n                    break\n                time.sleep_ms(1)\n            else:\n                self.data.irq(handler=None)\n                raise OSError(\"Sensor does not respond\")\n        else:\n            # wait polling for the trigger pulse\n            for _ in range(self.__wait_loop):\n                if self.data():\n                    break\n            else:\n                raise OSError(\"No trigger pulse found\")\n            for _ in range(5000):\n                if not self.data():\n                    break\n                time.sleep_us(100)\n            else:\n                raise OSError(\"Sensor does not respond\")\n\n        # shift in data, and gain & channel info\n        result = 0\n        for j in range(24 + self.GAIN):\n            state = disable_irq()\n            self.clock(True)\n            self.clock(False)\n            enable_irq(state)\n            result = (result << 1) | self.data()\n\n        # shift back the extra bits\n        result >>= self.GAIN\n\n        # check sign\n        if result > 0x7fffff:\n            result -= 0x1000000\n\n        return result\n\n    def read_average(self, times=3):\n        sum = 0\n        for i in range(times):\n            sum += self.read()\n        return sum / times\n\n    def read_lowpass(self):\n        self.filtered += self.time_constant * (self.read() - self.filtered)\n        return self.filtered\n\n    def get_value(self):\n        return self.read_lowpass() - self.OFFSET\n\n    def get_units(self):\n        return self.get_value() / self.SCALE\n\n    def tare(self, times=15):\n        self.set_offset(self.read_average(times))\n\n    def set_scale(self, scale):\n        self.SCALE = scale\n\n    def set_offset(self, offset):\n        self.OFFSET = offset\n\n    def set_time_constant(self, time_constant = None):\n        if time_constant is None:\n            return self.time_constant\n        elif 0 < time_constant < 1.0:\n            self.time_constant = time_constant\n\n    def power_down(self):\n        self.clock.value(False)\n        self.clock.value(True)\n\n    def power_up(self):\n        self.clock.value(False)\n","/lib/ext/smart_gbw/main.py":"\"\"\"SmartGBW's own work: the board starts this at every boot.\"\"\"\n\nfrom lib.ext.smart_gbw import smart_gbw\n\n\nasync def run():\n    await smart_gbw.run()\n","/lib/ext/smart_gbw/profile_controller.py":"\"\"\"Grind profiles: SINGLE, DOUBLE, CUSTOM.\n\nPersisted to /store/config/grinder_profiles.json. Port of\nsrc/controllers/profile_controller.cpp.\n\"\"\"\n\nimport json\nimport os\n\nfrom lib.ext.smart_gbw import grind_config as C\n\n_PROFILE_PATH = \"/store/config/grinder_profiles.json\"\n\n_DEFAULTS = {\n    C.Profile.SINGLE: {\"label\": \"Single\", \"mode\": C.Mode.WEIGHT, \"target_g\": 9.0,  \"target_ms\": 0},\n    C.Profile.DOUBLE: {\"label\": \"Double\", \"mode\": C.Mode.WEIGHT, \"target_g\": 18.0, \"target_ms\": 0},\n    C.Profile.CUSTOM: {\"label\": \"Custom\", \"mode\": C.Mode.WEIGHT, \"target_g\": 14.0, \"target_ms\": 0},\n}\n\n\nclass ProfileController:\n    def __init__(self):\n        self.profiles = {}\n        self.active_id = C.Profile.DOUBLE\n        self._load()\n\n    def _load(self):\n        try:\n            with open(_PROFILE_PATH) as f:\n                data = json.load(f)\n            self.profiles = {int(k): v for k, v in data[\"profiles\"].items()}\n            self.active_id = int(data.get(\"active\", C.Profile.DOUBLE))\n        except (OSError, ValueError, KeyError):\n            self.profiles = {k: dict(v) for k, v in _DEFAULTS.items()}\n            self.active_id = C.Profile.DOUBLE\n            self.save()\n\n    def save(self):\n        try:\n            os.stat(\"/store/config\")\n        except OSError:\n            try:\n                os.mkdir(\"/store\")\n            except OSError:\n                pass\n            try:\n                os.mkdir(\"/store/config\")\n            except OSError:\n                pass\n        with open(_PROFILE_PATH, \"w\") as f:\n            json.dump({\n                \"active\": self.active_id,\n                \"profiles\": {str(k): v for k, v in self.profiles.items()},\n            }, f)\n\n    def get(self, profile_id=None):\n        pid = self.active_id if profile_id is None else profile_id\n        return self.profiles.get(pid, _DEFAULTS[C.Profile.DOUBLE])\n\n    def set_active(self, profile_id):\n        self.active_id = profile_id\n        self.save()\n\n    def update(self, profile_id, **fields):\n        p = self.profiles.setdefault(profile_id, dict(_DEFAULTS[profile_id]))\n        p.update(fields)\n        self.save()\n","/lib/ext/smart_gbw/smart_gbw.py":"\"\"\"SmartGBW on the board.\n\nmain.py runs run(), which the board starts at every boot and restarts if it raises. It\nbuilds the sensor, the grinder, the profiles, the statistics, the controller and the screen,\nthen runs three loops until it is stopped:\n\n    the sampler      reads the HX711 at the interval in grind_config\n    the controller   GrindController.update() every 20 ms\n    the screen       UIManager.tick() every 200 ms\n\nLVGL's own timer is run by the display driver. The pins come from what the person has wired\nto the board: a device \"load_cell\" with dt_pin and sck_pin, and a device \"grinder_relay\" with\npin. Until both are wired, nothing is driven.\n\"\"\"\n\nimport asyncio\n\nfrom lib.sys import board\n\nfrom lib.ext.smart_gbw import grind_config as C\nfrom lib.ext.smart_gbw import grind_helpers\n\nNOT_WIRED = \"SmartGBW doesn't know its pins: wire a load_cell (dt_pin, sck_pin) and a grinder_relay (pin).\"\n\n_ctx = {\n    \"sensor\": None,\n    \"grinder\": None,\n    \"profiles\": None,\n    \"statistics\": None,\n    \"controller\": None,\n    \"ui\": None,\n    \"display\": None,\n}\n\n\ndef wiring():\n    \"\"\"(dt_pin, sck_pin, relay_pin) as wired, or None if either device isn't.\"\"\"\n    try:\n        cell = board.device(\"load_cell\")\n        relay = board.device(\"grinder_relay\")\n        return cell.dt_pin, cell.sck_pin, relay.pin\n    except (KeyError, AttributeError):\n        return None\n\n\nasync def run():\n    pins = wiring()\n    if pins is None:\n        print(\"[smart-gbw] \" + NOT_WIRED)\n        return\n    _init_display()\n    _init_runtime(pins)\n    loops = [_sampler_task(), _controller_task()]\n    if _ctx[\"ui\"] is not None:\n        loops.append(_ui_task())\n    try:\n        await asyncio.gather(*loops)\n    finally:\n        _ctx[\"grinder\"].stop()\n        grind_helpers.bind(None, _ctx[\"statistics\"], _ctx[\"profiles\"], None)\n\n\n# ----- init steps ---------------------------------------------------------\ndef _init_display():\n    \"\"\"Bring up the LVGL-backed display using pyDirect's display_manager.\n\n    display_manager.init_display() is idempotent and reads the panel/bus\n    config from the board manifest, so the same code works across boards\n    (Waveshare AMOLED, etc.). After it returns, LVGL is ready and widgets\n    can be created.\n    \"\"\"\n    try:\n        from lib.sys.display.display_manager import init_display\n        _ctx[\"display\"] = init_display()\n    except Exception as e:\n        print(\"[smart-gbw] display init failed: %s\" % e)\n        _ctx[\"display\"] = None\n\n\ndef _init_runtime(pins):\n    from lib.ext.smart_gbw.weight_sensor import WeightSensor\n    from lib.ext.smart_gbw.grinder import Grinder\n    from lib.ext.smart_gbw.profile_controller import ProfileController\n    from lib.ext.smart_gbw.statistics import StatisticsManager\n    from lib.ext.smart_gbw.grind_controller import GrindController\n    from lib.ext.smart_gbw.ui.ui_manager import UIManager\n\n    dt_pin, sck_pin, relay_pin = pins\n    sensor = WeightSensor(dt_pin, sck_pin)\n    grinder = Grinder(relay_pin)\n    profiles = ProfileController()\n    stats = StatisticsManager()\n    controller = GrindController(sensor, grinder, profiles, stats)\n    ui = UIManager(controller, sensor, grinder, profiles) if _ctx[\"display\"] is not None else None\n\n    _ctx.update({\n        \"sensor\": sensor,\n        \"grinder\": grinder,\n        \"profiles\": profiles,\n        \"statistics\": stats,\n        \"controller\": controller,\n        \"ui\": ui,\n    })\n\n    grind_helpers.bind(controller, stats, profiles, sensor)\n\n\n# ----- async tasks --------------------------------------------------------\nasync def _sampler_task():\n    \"\"\"Poll the HX711 at the configured interval.\"\"\"\n    sensor = _ctx[\"sensor\"]\n    interval = C.LOADCELL_SAMPLE_INTERVAL_MS\n    while True:\n        try:\n            sensor.read()\n        except OSError:\n            # Sensor disconnected / noisy — just skip this sample.\n            pass\n        except Exception as e:\n            print(\"[smart-gbw] sampler: %s\" % e)\n        await asyncio.sleep_ms(interval)\n\n\nasync def _controller_task():\n    \"\"\"Tick the grind state machine.\"\"\"\n    controller = _ctx[\"controller\"]\n    while True:\n        try:\n            controller.update()\n        except Exception as e:\n            print(\"[smart-gbw] controller: %s\" % e)\n        await asyncio.sleep_ms(20)\n\n\nasync def _ui_task():\n    \"\"\"Refresh the active screen from controller state.\n\n    200 ms is plenty for human-perceived weight readout; faster refreshes\n    just churn LVGL invalidations and risk re-entering the render path.\n    \"\"\"\n    ui = _ctx[\"ui\"]\n    while True:\n        try:\n            ui.tick()\n        except Exception as e:\n            print(\"[smart-gbw] ui: %s\" % e)\n        await asyncio.sleep_ms(200)\n","/lib/ext/smart_gbw/statistics.py":"\"\"\"Session statistics -> JSON Lines at /store/grind_sessions.jsonl.\n\nPort of src/system/statistics_manager.cpp. Each completed grind session is\nappended as a single JSON object, one per line. JS analytics view streams\nthese back over the WebREPL binary protocol.\n\"\"\"\n\nimport json\nimport os\nimport time\n\n_JSONL_PATH = \"/store/grind_sessions.jsonl\"\n_UPTIME_PATH = \"/store/config/grinder_uptime.json\"\n_MAX_LINE_BYTES = 32 * 1024  # defensive cap per session\n\n\nclass StatisticsManager:\n    def __init__(self, path=_JSONL_PATH):\n        self.path = path\n        self._ensure_parent()\n        self._total_uptime_minutes = 0\n        self._load_uptime()\n\n    def _ensure_parent(self):\n        parent = \"/store\"\n        try:\n            os.stat(parent)\n        except OSError:\n            try:\n                os.mkdir(parent)\n            except OSError:\n                pass\n\n    # ----- sessions -----------------------------------------------------------\n    def record_session(self, session):\n        line = json.dumps(session)\n        if len(line) > _MAX_LINE_BYTES:\n            session = dict(session)\n            session[\"measurements\"] = []\n            line = json.dumps(session) + \"\\n\"\n        else:\n            line = line + \"\\n\"\n        with open(self.path, \"a\") as f:\n            f.write(line)\n\n    def iter_sessions(self, limit=None, offset=0):\n        \"\"\"Stream sessions oldest-first. Used by the analytics RPC.\"\"\"\n        try:\n            f = open(self.path)\n        except OSError:\n            return\n        try:\n            idx = 0\n            yielded = 0\n            for line in f:\n                line = line.strip()\n                if not line:\n                    continue\n                if idx < offset:\n                    idx += 1\n                    continue\n                idx += 1\n                try:\n                    yield json.loads(line)\n                except ValueError:\n                    continue\n                yielded += 1\n                if limit is not None and yielded >= limit:\n                    return\n        finally:\n            f.close()\n\n    def count_sessions(self):\n        try:\n            f = open(self.path)\n        except OSError:\n            return 0\n        n = 0\n        try:\n            for line in f:\n                if line.strip():\n                    n += 1\n        finally:\n            f.close()\n        return n\n\n    def truncate(self):\n        try:\n            os.remove(self.path)\n        except OSError:\n            pass\n\n    # ----- uptime (total grinder run-time, in minutes) -----------------------\n    def _load_uptime(self):\n        try:\n            with open(_UPTIME_PATH) as f:\n                self._total_uptime_minutes = int(json.load(f).get(\"minutes\", 0))\n        except (OSError, ValueError):\n            self._total_uptime_minutes = 0\n\n    def update_uptime(self, minutes):\n        self._total_uptime_minutes += minutes\n        try:\n            os.stat(\"/store/config\")\n        except OSError:\n            try:\n                os.mkdir(\"/store/config\")\n            except OSError:\n                pass\n        with open(_UPTIME_PATH, \"w\") as f:\n            json.dump({\"minutes\": self._total_uptime_minutes,\n                       \"last_update\": time.time() if hasattr(time, \"time\") else 0}, f)\n\n    def total_uptime_minutes(self):\n        return self._total_uptime_minutes\n","/lib/ext/smart_gbw/tools/calibrate.py":"# === START_CONFIG_PARAMETERS ===\ndict(\n    info=dict(\n        name=\"Calibrate the scale\",\n        description=\"Set the scale from a known weight resting on it. Tare it empty first.\",\n        effects=dict(readOnly=False, destructive=False, openWorld=False),\n    ),\n    args=dict(\n        known_g=dict(label=\"The known weight in grams\", type=float, min=1, max=5000),\n    ),\n    safety=dict(confirm=True, timeout_s=10),\n)\n# === END_CONFIG_PARAMETERS ===\n\nfrom lib.ext.smart_gbw import grind_helpers\n\n\nasync def run(args, job):\n    return grind_helpers.calibrate(args.known_g)\n","/lib/ext/smart_gbw/tools/profiles.py":"# === START_CONFIG_PARAMETERS ===\ndict(\n    info=dict(\n        name=\"Grind profiles\",\n        description=\"The grind profiles and which one is active.\",\n        effects=dict(readOnly=True, destructive=False, openWorld=False),\n    ),\n    args=dict(),\n)\n# === END_CONFIG_PARAMETERS ===\n\nfrom lib.ext.smart_gbw import grind_helpers\n\n\nasync def run(args, job):\n    return grind_helpers.profiles()\n","/lib/ext/smart_gbw/tools/select_profile.py":"# === START_CONFIG_PARAMETERS ===\ndict(\n    info=dict(\n        name=\"Select profile\",\n        description=\"Make a profile the active one.\",\n        effects=dict(readOnly=False, destructive=False, openWorld=False),\n    ),\n    args=dict(\n        profile_id=dict(label=\"Profile number\", type=int, min=0),\n    ),\n)\n# === END_CONFIG_PARAMETERS ===\n\nfrom lib.ext.smart_gbw import grind_helpers\n\n\nasync def run(args, job):\n    return grind_helpers.select_profile(args.profile_id)\n","/lib/ext/smart_gbw/tools/sessions.py":"# === START_CONFIG_PARAMETERS ===\ndict(\n    info=dict(\n        name=\"Grind sessions\",\n        description=\"Whole sessions with every weight sample, oldest first. They are large, so ask for one or a few.\",\n        effects=dict(readOnly=True, destructive=False, openWorld=False),\n    ),\n    args=dict(\n        limit=dict(label=\"How many\", type=int, min=1, max=10000, value=1, optional=True),\n        offset=dict(label=\"Skip this many\", type=int, min=0, value=0, optional=True),\n    ),\n)\n# === END_CONFIG_PARAMETERS ===\n\nfrom lib.ext.smart_gbw import grind_helpers\n\n\nasync def run(args, job):\n    return grind_helpers.sessions(args.limit, args.offset)\n","/lib/ext/smart_gbw/tools/start.py":"# === START_CONFIG_PARAMETERS ===\ndict(\n    info=dict(\n        name=\"Start a grind\",\n        description=\"Run the grinder motor for the target of a profile. The cup has to be in place.\",\n        effects=dict(readOnly=False, destructive=False, openWorld=False),\n    ),\n    args=dict(\n        profile_id=dict(label=\"Profile number, the active one if left out\", type=int, min=0, optional=True),\n    ),\n    safety=dict(confirm=True, timeout_s=10),\n)\n# === END_CONFIG_PARAMETERS ===\n\nfrom lib.ext.smart_gbw import grind_helpers\n\n\nasync def run(args, job):\n    return grind_helpers.start(args.profile_id)\n","/lib/ext/smart_gbw/tools/state.py":"# === START_CONFIG_PARAMETERS ===\ndict(\n    info=dict(\n        name=\"Grinder state\",\n        description=\"The live weight on the scale, the flow, the phase of a grind and how the last one ended. If SmartGBW is not running, says so and whether its pins are wired.\",\n        effects=dict(readOnly=True, destructive=False, openWorld=False),\n    ),\n    args=dict(),\n)\n# === END_CONFIG_PARAMETERS ===\n\nfrom lib.ext.smart_gbw import grind_helpers\n\n\nasync def run(args, job):\n    return grind_helpers.state()\n","/lib/ext/smart_gbw/tools/stop.py":"# === START_CONFIG_PARAMETERS ===\ndict(\n    info=dict(\n        name=\"Stop the grind\",\n        description=\"Stop the grinder motor now.\",\n        effects=dict(readOnly=False, destructive=False, openWorld=False),\n    ),\n    args=dict(),\n)\n# === END_CONFIG_PARAMETERS ===\n\nfrom lib.ext.smart_gbw import grind_helpers\n\n\nasync def run(args, job):\n    return grind_helpers.stop()\n","/lib/ext/smart_gbw/tools/summaries.py":"# === START_CONFIG_PARAMETERS ===\ndict(\n    info=dict(\n        name=\"Grind summaries\",\n        description=\"One line per grind-by-weight session, oldest first: when, the target, the final weight, pulses, latency and flow. Use sessions for one grind with its weight curve.\",\n        effects=dict(readOnly=True, destructive=False, openWorld=False),\n    ),\n    args=dict(\n        limit=dict(label=\"How many\", type=int, min=1, max=10000, optional=True),\n        offset=dict(label=\"Skip this many\", type=int, min=0, value=0, optional=True),\n    ),\n)\n# === END_CONFIG_PARAMETERS ===\n\nfrom lib.ext.smart_gbw import grind_helpers\n\n\nasync def run(args, job):\n    return grind_helpers.summaries(args.limit, args.offset)\n","/lib/ext/smart_gbw/tools/tare.py":"# === START_CONFIG_PARAMETERS ===\ndict(\n    info=dict(\n        name=\"Tare the scale\",\n        description=\"Zero the scale with whatever is on it now.\",\n        effects=dict(readOnly=False, destructive=False, openWorld=False),\n    ),\n    args=dict(),\n)\n# === END_CONFIG_PARAMETERS ===\n\nfrom lib.ext.smart_gbw import grind_helpers\n\n\nasync def run(args, job):\n    return grind_helpers.tare()\n","/lib/ext/smart_gbw/tools/update_profile.py":"# === START_CONFIG_PARAMETERS ===\ndict(\n    info=dict(\n        name=\"Change a profile\",\n        description=\"Change the target of a profile: target_g for a grind by weight, target_ms for a grind by time.\",\n        effects=dict(readOnly=False, destructive=False, openWorld=False),\n    ),\n    args=dict(\n        profile_id=dict(label=\"Profile number\", type=int, min=0),\n        target_g=dict(label=\"Target weight in grams\", type=float, min=1, max=100, optional=True),\n        target_ms=dict(label=\"Target time in ms\", type=int, min=500, max=60000, optional=True),\n    ),\n)\n# === END_CONFIG_PARAMETERS ===\n\nfrom lib.ext.smart_gbw import grind_helpers\n\n\nasync def run(args, job):\n    return grind_helpers.update_profile(args.profile_id, args.target_g, args.target_ms)\n","/lib/ext/smart_gbw/ui/screens/calibration_screen.py":"\"\"\"Calibration screen - zero + known-weight calibration.\n\nPort of src/ui/screens/calibration_screen.cpp.\n\"\"\"\n\nimport lvgl as lv\n\nfrom lib.ext.smart_gbw.ui import theme\n\n_KNOWN_WEIGHT_G = 100.0\n\n\nclass CalibrationScreen:\n    def __init__(self, ui_manager):\n        self.ui = ui_manager\n        self._scr = lv.obj()\n        theme.apply_root(self._scr)\n\n        self._prompt = theme.medium_label(self._scr, \"Calibration\", color=theme.ACCENT)\n        self._prompt.align(lv.ALIGN.TOP_MID, 0, 16)\n\n        self._status = theme.medium_label(self._scr, \"Remove all weight then tap TARE\", color=theme.FG)\n        self._status.align(lv.ALIGN.CENTER, 0, -20)\n\n        self._tare_btn = lv.button(self._scr)\n        self._tare_btn.set_size(140, 48)\n        self._tare_btn.align(lv.ALIGN.CENTER, -80, 40)\n        bl = lv.label(self._tare_btn)\n        bl.set_text(\"TARE\")\n        bl.center()\n        self._tare_btn.add_event_cb(self._on_tare, lv.EVENT.CLICKED, None)\n\n        self._cal_btn = lv.button(self._scr)\n        self._cal_btn.set_size(180, 48)\n        self._cal_btn.align(lv.ALIGN.CENTER, 80, 40)\n        self._cal_btn.set_style_bg_color(theme.ACCENT, 0)\n        bl2 = lv.label(self._cal_btn)\n        bl2.set_text(\"CALIBRATE 100g\")\n        bl2.center()\n        self._cal_btn.add_event_cb(self._on_calibrate, lv.EVENT.CLICKED, None)\n\n        self._done_btn = lv.button(self._scr)\n        self._done_btn.set_size(120, 40)\n        self._done_btn.align(lv.ALIGN.BOTTOM_MID, 0, -12)\n        bl3 = lv.label(self._done_btn)\n        bl3.set_text(\"Done\")\n        bl3.center()\n        self._done_btn.add_event_cb(self._on_done, lv.EVENT.CLICKED, None)\n\n    def activate(self):\n        lv.screen_load(self._scr)\n\n    def refresh(self):\n        pass\n\n    def _on_tare(self, _evt):\n        self.ui.sensor.tare()\n        self._status.set_text(\"Tared. Place %.0fg then CALIBRATE.\" % _KNOWN_WEIGHT_G)\n\n    def _on_calibrate(self, _evt):\n        # Compute scale factor: raw = (scale * g) + offset, so scale = raw / g\n        # We rely on hx711_gpio's read_average / get_value path; set_scale then use get_units.\n        raw = self.ui.sensor._hx.read_average(15) - self.ui.sensor._hx.OFFSET\n        if _KNOWN_WEIGHT_G > 0:\n            scale = raw / _KNOWN_WEIGHT_G\n            self.ui.sensor.set_scale(scale)\n            self.ui.sensor.save_calibration()\n            self._status.set_text(\"Scale = %.3f\" % scale)\n\n    def _on_done(self, _evt):\n        if self.ui.sensor.is_calibrated():\n            self.ui.show(\"ready\")\n","/lib/ext/smart_gbw/ui/screens/grinding_screen.py":"\"\"\"Grinding screen - live progress during a grind session.\n\nPort of src/ui/screens/grinding_screen.cpp (text/arc variant). Chart variant\nlives as a sibling screen if needed later.\n\"\"\"\n\nimport lvgl as lv\n\nfrom lib.ext.smart_gbw import grind_config as C\nfrom lib.ext.smart_gbw.ui import theme\n\n\n_PHASE_TEXT = {\n    C.Phase.TARING: \"TARING\",\n    C.Phase.TARE_CONFIRM: \"TARED\",\n    C.Phase.PREDICTIVE: \"GRINDING\",\n    C.Phase.FINAL_SETTLING: \"SETTLING\",\n    C.Phase.PULSE_DECISION: \"CHECK\",\n    C.Phase.PULSE_EXECUTE: \"PULSE\",\n    C.Phase.PULSE_SETTLING: \"SETTLING\",\n    C.Phase.TIME_GRINDING: \"TIMED\",\n    C.Phase.COMPLETED: \"DONE\",\n    C.Phase.TIMEOUT: \"TIMEOUT\",\n    C.Phase.PRIME: \"PRIME\",\n}\n\n\nclass GrindingScreen:\n    def __init__(self, ui_manager):\n        self.ui = ui_manager\n        self._scr = lv.obj()\n        theme.apply_root(self._scr)\n\n        self._weight_lbl = theme.big_label(self._scr, \"0.0 g\", color=theme.ACCENT)\n        self._weight_lbl.align(lv.ALIGN.CENTER, 0, -24)\n\n        self._target_lbl = theme.medium_label(self._scr, \"/ 0.0 g\", color=theme.MUTED)\n        self._target_lbl.align(lv.ALIGN.CENTER, 0, 24)\n\n        self._phase_lbl = theme.medium_label(self._scr, \"\", color=theme.FG)\n        self._phase_lbl.align(lv.ALIGN.TOP_MID, 0, 8)\n\n        self._stop_btn = lv.button(self._scr)\n        self._stop_btn.set_size(160, 48)\n        self._stop_btn.align(lv.ALIGN.BOTTOM_MID, 0, -16)\n        self._stop_btn.set_style_bg_color(theme.ERR, 0)\n        bl = lv.label(self._stop_btn)\n        bl.set_text(\"STOP\")\n        bl.center()\n        self._stop_btn.add_event_cb(self._on_stop, lv.EVENT.CLICKED, None)\n\n    def activate(self):\n        lv.screen_load(self._scr)\n        c = self.ui.controller\n        if c.mode == C.Mode.WEIGHT:\n            self._target_lbl.set_text(\"/ %.1f g\" % c.target_weight)\n        else:\n            self._target_lbl.set_text(\"/ %.1f s\" % (c.target_time_ms / 1000.0))\n\n    def refresh(self):\n        c = self.ui.controller\n        weight_text = \"%.2f g\" % self.ui.sensor.current()\n        if weight_text != getattr(self, \"_last_weight_text\", None):\n            self._weight_lbl.set_text(weight_text)\n            self._last_weight_text = weight_text\n\n        if c.phase == C.Phase.COMPLETED:\n            phase_text = C.RESULT_NAMES.get(c.last_result, \"?\")\n            color = theme.OK if c.last_result == C.Result.SUCCESS else theme.WARN\n        else:\n            phase_text = _PHASE_TEXT.get(c.phase, \"\")\n            color = theme.FG\n\n        if phase_text != getattr(self, \"_last_phase_text\", None):\n            self._phase_lbl.set_text(phase_text)\n            self._phase_lbl.set_style_text_color(color, 0)\n            self._last_phase_text = phase_text\n\n    def _on_stop(self, _evt):\n        self.ui.stop_grind()\n","/lib/ext/smart_gbw/ui/screens/menu_screen.py":"\"\"\"Menu screen - top-level settings entry.\n\nPort of src/ui/screens/menu_screen.cpp. Minimal version: lists entries that\ndrive calibration and the back action; edit/autotune to follow.\n\"\"\"\n\nimport lvgl as lv\n\nfrom lib.ext.smart_gbw.ui import theme\n\n\nclass MenuScreen:\n    def __init__(self, ui_manager):\n        self.ui = ui_manager\n        self._scr = lv.obj()\n        theme.apply_root(self._scr)\n\n        title = theme.medium_label(self._scr, \"Menu\", color=theme.ACCENT)\n        title.align(lv.ALIGN.TOP_MID, 0, 8)\n\n        self._list = lv.list(self._scr)\n        self._list.set_size(lv.pct(90), lv.pct(70))\n        self._list.align(lv.ALIGN.CENTER, 0, 0)\n\n        self._add_entry(\"Calibrate scale\", lambda _e: self.ui.show(\"calibration\"))\n        self._add_entry(\"Tare\", lambda _e: self.ui.sensor.tare())\n        self._add_entry(\"Back\", lambda _e: self.ui.show(\"ready\"))\n\n    def activate(self):\n        lv.screen_load(self._scr)\n\n    def refresh(self):\n        pass\n\n    def _add_entry(self, text, cb):\n        btn = self._list.add_button(None, text)\n        btn.add_event_cb(cb, lv.EVENT.CLICKED, None)\n","/lib/ext/smart_gbw/ui/screens/ready_screen.py":"\"\"\"Ready screen - resting state with profile selector + live weight.\n\nPort of src/ui/screens/ready_screen.cpp.\n\"\"\"\n\nimport lvgl as lv\n\nfrom lib.ext.smart_gbw import grind_config as C\nfrom lib.ext.smart_gbw.ui import theme\n\n\nclass ReadyScreen:\n    def __init__(self, ui_manager):\n        self.ui = ui_manager\n        self._scr = lv.obj()\n        theme.apply_root(self._scr)\n\n        self._weight_lbl = theme.big_label(self._scr, \"0.0 g\", color=theme.ACCENT)\n        self._weight_lbl.align(lv.ALIGN.TOP_MID, 0, 20)\n\n        self._profile_lbl = theme.medium_label(self._scr, \"\", color=theme.FG)\n        self._profile_lbl.align(lv.ALIGN.CENTER, 0, 0)\n\n        # GRIND button\n        self._grind_btn = lv.button(self._scr)\n        self._grind_btn.set_size(160, 64)\n        self._grind_btn.align(lv.ALIGN.BOTTOM_MID, 0, -20)\n        self._grind_btn.set_style_bg_color(theme.ACCENT, 0)\n        bl = lv.label(self._grind_btn)\n        bl.set_text(\"GRIND\")\n        bl.center()\n        self._grind_btn.add_event_cb(self._on_grind, lv.EVENT.CLICKED, None)\n\n        # Menu button (top-left)\n        self._menu_btn = lv.button(self._scr)\n        self._menu_btn.set_size(40, 40)\n        self._menu_btn.align(lv.ALIGN.TOP_LEFT, 8, 8)\n        ml = lv.label(self._menu_btn)\n        ml.set_text(lv.SYMBOL.LIST)\n        ml.center()\n        self._menu_btn.add_event_cb(self._on_menu, lv.EVENT.CLICKED, None)\n\n        # Tare (top-right)\n        self._tare_btn = lv.button(self._scr)\n        self._tare_btn.set_size(40, 40)\n        self._tare_btn.align(lv.ALIGN.TOP_RIGHT, -8, 8)\n        tl = lv.label(self._tare_btn)\n        tl.set_text(\"T\")\n        tl.center()\n        self._tare_btn.add_event_cb(self._on_tare, lv.EVENT.CLICKED, None)\n\n        # Profile cycle (tap profile label)\n        self._profile_lbl.add_flag(lv.obj.FLAG.CLICKABLE)\n        self._profile_lbl.add_event_cb(self._on_cycle_profile, lv.EVENT.CLICKED, None)\n\n    def activate(self):\n        lv.screen_load(self._scr)\n        self._update_profile_text()\n\n    def refresh(self):\n        # Avoid set_text on every tick — LVGL invalidates and reflows the\n        # label whether the value changed or not.\n        text = \"%.1f g\" % self.ui.sensor.current()\n        if text != getattr(self, \"_last_weight_text\", None):\n            self._weight_lbl.set_text(text)\n            self._last_weight_text = text\n\n    # ----- callbacks ----------------------------------------------------------\n    def _on_grind(self, _evt):\n        self.ui.start_grind()\n\n    def _on_menu(self, _evt):\n        self.ui.show(\"menu\")\n\n    def _on_tare(self, _evt):\n        self.ui.sensor.tare()\n\n    def _on_cycle_profile(self, _evt):\n        ids = sorted(self.ui.profiles.profiles.keys())\n        cur = self.ui.profiles.active_id\n        nxt = ids[(ids.index(cur) + 1) % len(ids)] if cur in ids else ids[0]\n        self.ui.profiles.set_active(nxt)\n        self._update_profile_text()\n\n    def _update_profile_text(self):\n        p = self.ui.profiles.get()\n        if p[\"mode\"] == C.Mode.WEIGHT:\n            self._profile_lbl.set_text(\"%s  %.1fg\" % (p[\"label\"], p[\"target_g\"]))\n        else:\n            self._profile_lbl.set_text(\"%s  %.1fs\" % (p[\"label\"], p[\"target_ms\"] / 1000.0))\n","/lib/ext/smart_gbw/ui/theme.py":"\"\"\"LVGL theme for the coffee grinder UI.\n\nColors match the original src/config/theme.h. Screens pull constants from here\nso restyling only needs one touch point.\n\"\"\"\n\nimport lvgl as lv\n\nimport fs_driver\n\nBG = lv.color_hex(0x1A1612)\nFG = lv.color_hex(0xF4E9D8)\nACCENT = lv.color_hex(0xC89B6B)\nACCENT_DARK = lv.color_hex(0x8B6A3F)\nOK = lv.color_hex(0x4CAF50)\nWARN = lv.color_hex(0xFF9800)\nERR = lv.color_hex(0xF44336)\nMUTED = lv.color_hex(0x7A7168)\n\n\n# Register an LVGL filesystem driver under prefix \"A\" so binfont_create can\n# read /lib/fonts/*.bin. fs_register is idempotent across imports.\n_fs_drv = lv.fs_drv_t()\nfs_driver.fs_register(_fs_drv, \"A\")\n\n\ndef _load_binfont(path):\n    try:\n        return lv.binfont_create(\"A:\" + path)\n    except Exception as e:\n        print(\"[smart-gbw] failed to load %s: %s\" % (path, e))\n        return None\n\n\ndef _pick_font(*candidates):\n    \"\"\"Return the first available LVGL font object from a list of names.\n\n    Names ending in .bin are loaded from the filesystem; others are looked up\n    as attributes on the lvgl module (compiled-in fonts).\n    \"\"\"\n    for name in candidates:\n        if name.endswith(\".bin\"):\n            f = _load_binfont(name)\n            if f is not None:\n                return f\n        else:\n            f = getattr(lv, name, None)\n            if f is not None:\n                return f\n    return None\n\n\n# Prefer the firmware's bundled Montserrat; fall back to compiled-in sizes.\nBIG_FONT = _pick_font(\n    \"/lib/fonts/montserrat48.bin\",\n    \"font_montserrat_48\",\n    \"font_montserrat_28\",\n    \"font_montserrat_22\",\n)\nMEDIUM_FONT = _pick_font(\n    \"/lib/fonts/montserrat24.bin\",\n    \"font_montserrat_24\",\n    \"font_montserrat_18\",\n    \"font_montserrat_14\",\n)\n\n\ndef apply_root(root):\n    root.set_style_bg_color(BG, 0)\n    root.set_style_text_color(FG, 0)\n\n\ndef _label(parent, text, color, font):\n    lbl = lv.label(parent)\n    lbl.set_text(text)\n    lbl.set_style_text_color(color if color is not None else FG, 0)\n    if font is not None:\n        lbl.set_style_text_font(font, 0)\n    return lbl\n\n\ndef big_label(parent, text, color=None):\n    return _label(parent, text, color, BIG_FONT)\n\n\ndef medium_label(parent, text, color=None):\n    return _label(parent, text, color, MEDIUM_FONT)\n","/lib/ext/smart_gbw/ui/ui_manager.py":"\"\"\"LVGL UI manager. Routes state transitions to the appropriate screen.\n\nPort of src/ui/ui_manager.cpp. An lv.timer ticks the controller and pumps\nscreen refresh; the LVGL task handler itself is driven by smart_gbw._lvgl_task.\n\"\"\"\n\nimport lvgl as lv\n\nfrom lib.ext.smart_gbw import grind_config as C\nfrom lib.ext.smart_gbw.ui.screens.ready_screen import ReadyScreen\nfrom lib.ext.smart_gbw.ui.screens.grinding_screen import GrindingScreen\nfrom lib.ext.smart_gbw.ui.screens.menu_screen import MenuScreen\nfrom lib.ext.smart_gbw.ui.screens.calibration_screen import CalibrationScreen\n\n\nclass UIManager:\n    def __init__(self, controller, sensor, grinder, profiles):\n        self.controller = controller\n        self.sensor = sensor\n        self.grinder = grinder\n        self.profiles = profiles\n\n        self._display = lv.display_get_default()\n        self._screens = {\n            \"ready\": ReadyScreen(self),\n            \"grinding\": GrindingScreen(self),\n            \"menu\": MenuScreen(self),\n            \"calibration\": CalibrationScreen(self),\n        }\n        self._current = None\n\n        if not self.sensor.is_calibrated():\n            self.show(\"calibration\")\n        else:\n            self.show(\"ready\")\n\n        # Controller + screen refresh are driven from the ensure_init async\n        # task loop instead of lv.timer so that asyncio can yield between ticks.\n        self._tick_timer = None\n\n    # ----- navigation ---------------------------------------------------------\n    def show(self, name):\n        if self._current == name:\n            return\n        self._current = name\n        self._screens[name].activate()\n\n    # ----- tick ---------------------------------------------------------------\n    def tick(self):\n        \"\"\"Called from smart_gbw._ui_task at ~200 ms cadence.\n\n        Only refreshes the active screen — the controller is ticked\n        independently by sgbw_controller. Calling controller.update() here\n        too would double-tick the state machine.\n        \"\"\"\n        screen = self._screens.get(self._current)\n        if screen is not None:\n            screen.refresh()\n\n    # ----- actions triggered from screens ------------------------------------\n    def start_grind(self, profile_id=None):\n        profile = self.profiles.get(profile_id)\n        if profile[\"mode\"] == C.Mode.WEIGHT:\n            self.controller.start_weight(profile[\"target_g\"], profile_id=profile_id or self.profiles.active_id)\n        else:\n            self.controller.start_time(profile[\"target_ms\"], profile_id=profile_id or self.profiles.active_id)\n        self.show(\"grinding\")\n\n    def stop_grind(self):\n        self.controller.stop()\n        self.show(\"ready\")\n","/lib/ext/smart_gbw/weight_sensor.py":"\"\"\"Load cell wrapper around HX711.\n\nMaintains a lightweight ring buffer of recent samples for flow-rate\ncalculation and settled-weight detection. Port of src/hardware/WeightSensor.cpp.\nThe sampling loop is an asyncio task owned by smart_gbw.ensure_init().\n\nIf the HX711 hardware can't be initialized (no load cell wired), falls\nback to a software mock so the rest of the runtime can boot for headless\nUI testing. Mirrors the DEBUG_ENABLE_LOADCELL_MOCK path from the original\nC++ project.\n\"\"\"\n\nimport time\nimport json\nimport os\n\nfrom machine import Pin\n\nfrom lib.ext.smart_gbw.grind_config import (\n    SCALE_SETTLING_TOLERANCE_G,\n)\n\n_CAL_PATH = \"/store/config/grinder_cal.json\"\n\n\nclass _MockHX711:\n    \"\"\"Drop-in stand-in for hx711_gpio.HX711 when no load cell is attached.\n\n    Exposes the same surface used by WeightSensor: SCALE/OFFSET attrs,\n    set_scale/set_offset/set_time_constant, get_units, read_average, tare.\n    Returns 0.0 g with deterministic micro-noise so settling logic still\n    converges. simulate_grams(g) lets test code drive a target weight.\n    \"\"\"\n\n    def __init__(self):\n        self.SCALE = 1.0\n        self.OFFSET = 0.0\n        self._time_constant = 0.25\n        self._target = 0.0\n        self._n = 0\n\n    def set_time_constant(self, v): self._time_constant = v\n    def set_scale(self, s):         self.SCALE = s\n    def set_offset(self, o):        self.OFFSET = o\n\n    def get_units(self):\n        # Tiny pseudo-random jitter (±0.002 g) without needing `random`.\n        self._n = (self._n + 1) & 0xFF\n        jitter = ((self._n % 5) - 2) * 0.001\n        return self._target + jitter\n\n    def read_average(self, times=15):\n        return self._target * self.SCALE + self.OFFSET\n\n    def tare(self, times=15):\n        self.OFFSET = 0.0\n        self._target = 0.0\n\n    def simulate_grams(self, g):\n        self._target = float(g)\n\n\nclass WeightSensor:\n    def __init__(self, dt_pin, sck_pin, buffer_size=128):\n        try:\n            from lib.ext.smart_gbw.hx711_gpio import HX711\n            self._dt = Pin(dt_pin, Pin.IN, pull=Pin.PULL_DOWN)\n            self._sck = Pin(sck_pin, Pin.OUT)\n            self._hx = HX711(self._sck, self._dt)\n            self._hx.set_time_constant(0.25)\n            self.is_mock = False\n        except OSError as e:\n            print(\"[smart-gbw] HX711 not responding (%s) — falling back to mock load cell\" % e)\n            self._dt = self._sck = None\n            self._hx = _MockHX711()\n            self.is_mock = True\n\n        self._buffer_size = buffer_size\n        self._samples = []  # list of (ticks_ms, grams)\n        self._calibrated = False\n        self._load_calibration()\n\n    # ----- calibration --------------------------------------------------------\n    def _load_calibration(self):\n        try:\n            with open(_CAL_PATH) as f:\n                cal = json.load(f)\n            self._hx.set_scale(cal[\"scale\"])\n            self._hx.set_offset(cal[\"offset\"])\n            self._calibrated = True\n        except (OSError, ValueError, KeyError):\n            self._hx.set_scale(1.0)\n            self._calibrated = False\n\n    def save_calibration(self):\n        try:\n            os.stat(\"/store/config\")\n        except OSError:\n            try:\n                os.mkdir(\"/store\")\n            except OSError:\n                pass\n            try:\n                os.mkdir(\"/store/config\")\n            except OSError:\n                pass\n        with open(_CAL_PATH, \"w\") as f:\n            json.dump({\"scale\": self._hx.SCALE, \"offset\": self._hx.OFFSET}, f)\n\n    def is_calibrated(self):\n        return self._calibrated\n\n    def tare(self, times=15):\n        self._hx.tare(times)\n        self._samples.clear()\n\n    def set_scale(self, scale):\n        self._hx.set_scale(scale)\n        self._calibrated = True\n\n    # ----- sampling -----------------------------------------------------------\n    def read(self):\n        g = self._hx.get_units()\n        now = time.ticks_ms()\n        self._samples.append((now, g))\n        if len(self._samples) > self._buffer_size:\n            self._samples.pop(0)\n        return g\n\n    def current(self):\n        return self._samples[-1][1] if self._samples else 0.0\n\n    def flow_rate_gps(self, window_ms=500):\n        if len(self._samples) < 2:\n            return 0.0\n        now, _ = self._samples[-1]\n        cutoff = time.ticks_add(now, -window_ms)\n        head = None\n        for t, g in self._samples:\n            if time.ticks_diff(t, cutoff) >= 0:\n                head = (t, g)\n                break\n        if head is None:\n            head = self._samples[0]\n        t0, g0 = head\n        t1, g1 = self._samples[-1]\n        dt = time.ticks_diff(t1, t0) / 1000.0\n        return (g1 - g0) / dt if dt > 0 else 0.0\n\n    def is_settled(self, tolerance=SCALE_SETTLING_TOLERANCE_G, window_ms=400):\n        if len(self._samples) < 3:\n            return False\n        now, _ = self._samples[-1]\n        cutoff = time.ticks_add(now, -window_ms)\n        recent = [g for (t, g) in self._samples if time.ticks_diff(t, cutoff) >= 0]\n        if len(recent) < 3:\n            return False\n        mean = sum(recent) / len(recent)\n        var = sum((g - mean) ** 2 for g in recent) / len(recent)\n        return (var ** 0.5) <= tolerance\n\n\n"};

